//Basic Operation Data



void mokaSwitchOff(lv_event_t * e){
	setMokaStatus(0);
}

void preheatingOn(lv_event_t * e)
{
	setMokaStatus(1);
}

void calibrate(lv_event_t * e)
{
	if(getMokaStatus() == 1 && getTargetHeatingTemp() >=100.0){
		calibrateBoiling();
	}
}

void boilingOn(lv_event_t * e)
{
	if(getMokaStatus() != 2){
		setMokaStatus(2);
	}
	else{
		skipBloom();
	}
}

void manualBloomPhase(lv_event_t * e)
{
	//setMokaStatus(2);
	setManualBloomTime(300.0);
}

void decreaseTargetTemp(lv_event_t * e)
{
	float aux=0;
	if(getMokaStatus() == 1){
		aux = getTargetHeatingTemp();
		aux = aux -1.0 ;
		setTargetHeatingTemp(aux);
	}
	if(getMokaStatus() == 2){
		aux = getTargetBoilingTemp();
		aux = aux -1.0 ;
		setTargetBoilingTemp(aux);
	}
	//lv_timer_handler();
}

void increaseTargetTemp(lv_event_t * e)
{
	
float aux=0;
	if(getMokaStatus() == 1){
		aux = getTargetHeatingTemp();
		aux = aux +1.0 ;
		setTargetHeatingTemp(aux);
	}
	if(getMokaStatus() == 2){
		aux = getTargetBoilingTemp();
		aux = aux +1.0 ;
		setTargetBoilingTemp(aux);
	}
	//lv_timer_handler();
}

void saveTargetTemp(lv_event_t * e){
	if(getMokaStatus() == 1){
		saveTargetHeatingTemp(getTargetHeatingTemp());
	}
	if(getMokaStatus() == 2){
		saveTargetBoilingTemp(getTargetBoilingTemp());
	}
}

